  #corebar .gem{font-size:20px;color:#6fe8d8;filter:drop-shadow(0 0 6px #2ec9b8)}
  #coretrack{width:190px;height:14px;background:rgba(8,6,16,.8);border:1px solid rgba(111,232,216,.3);border-radius:7px;overflow:hidden}
  #corefill{height:100%;width:100%;border-radius:6px;transition:width .25s}
  #corenum{font-size:12px;color:#9fd8d0;min-width:40px}
  #essence{font-size:17px;color:#ffd77a;text-shadow:0 0 8px rgba(255,180,80,.5)}
  #wavetag{font-size:14px;color:#d8c8e8}
  #preview{font-size:11px;color:#a898c0;max-width:280px;line-height:1.35}
  #besttag{font-size:11px;color:#c8a86a}
  #epop{position:fixed;left:150px;top:70px;font-size:15px;color:#ffd77a;opacity:0;z-index:11;pointer-events:none;text-shadow:0 0 8px rgba(255,190,90,.8)}
  #epop.pop{animation:epop 1s ease-out}
  @keyframes epop{0%{opacity:1;transform:translateY(0)}100%{opacity:0;transform:translateY(-26px)}}

  /* boss bar */
  #bossbar{position:fixed;top:14px;left:50%;transform:translateX(-50%);width:min(480px,60vw);display:none;z-index:10;pointer-events:none}
  #bossname{font-size:13px;color:#f0c8b0;text-align:center;letter-spacing:3px;margin-bottom:4px;text-shadow:0 0 6px rgba(220,90,60,.6)}
  #bosstrack{height:12px;background:rgba(10,6,10,.85);border:1px solid rgba(230,120,80,.4);border-radius:6px;overflow:hidden}
  #bossfill{height:100%;width:100%;background:linear-gradient(90deg,#c94a2e,#e88a5f);transition:width .2s}

  /* top-right buttons */
  #tr{position:fixed;right:14px;top:12px;z-index:12;display:flex;gap:8px;align-items:flex-start}
  #tr button{width:40px;height:40px;border-radius:9px;border:1px solid rgba(255,215,122,.3);background:rgba(18,12,28,.85);color:#ffd77a;font-size:16px;cursor:pointer}
  #tr button.on{background:rgba(90,60,20,.9)}
  #bestwrap{position:fixed;right:14px;top:58px;z-index:10;color:#c8a86a;font-size:12px;text-align:right;pointer-events:none}

  /* call wave */
  #callbtn{position:fixed;bottom:118px;left:50%;transform:translateX(-50%);z-index:12;display:none;padding:10px 26px;font-size:16px;color:#0e0a18;background:linear-gradient(180deg,#ffd77a,#e8a84f);border:none;border-radius:22px;cursor:pointer;letter-spacing:2px;box-shadow:0 0 18px rgba(255,190,90,.45)}
  #callbtn.bonus{animation:pulse 1.2s infinite}
  @keyframes pulse{0%,100%{box-shadow:0 0 12px rgba(255,190,90,.35)}50%{box-shadow:0 0 26px rgba(255,200,100,.75)}}

  /* build cards */
  #cardwrap{position:fixed;bottom:12px;left:50%;transform:translateX(-50%);z-index:12;text-align:center;pointer-events:none}
  #cardeh{font-size:12px;color:#a898c0;margin-bottom:6px;text-shadow:0 1px 4px #000}
  #cards{display:none;gap:9px;pointer-events:none;justify-content:center}
  #cards.on{display:flex}
  .card{position:relative;width:78px;padding:9px 4px 7px;background:rgba(18,12,28,.9);border:1px solid rgba(255,215,122,.25);border-radius:10px;cursor:pointer;text-align:center;transition:transform .12s,border-color .12s;pointer-events:auto}
  .card:hover{transform:translateY(-3px);border-color:rgba(255,215,122,.7)}
  .card.dim{opacity:.38;pointer-events:none}
  .card .glyph{font-size:21px}
  .card .cn{font-size:12px;color:#e8dcc8;margin-top:2px}
  .card .cc{font-size:11px;color:#ffd77a}
  .card .ck{position:absolute;left:5px;top:4px;font-size:10px;color:#8a7aa0}

  /* actives skill bar */
  #skills{position:fixed;right:14px;bottom:14px;z-index:13;display:flex;gap:10px}
  .skill{position:relative;width:52px;height:52px;border-radius:10px;background:rgba(18,12,28,.85);border:1px solid rgba(255,215,122,.3);cursor:pointer;overflow:hidden;display:flex;align-items:center;justify-content:center}
  .skill .sg{font-size:24px;color:#c8bca8;transition:color .2s}
  .skill.ready .sg{color:#ffe0a8;text-shadow:0 0 10px rgba(255,190,90,.8)}
  .skill .scd{position:absolute;left:0;bottom:0;width:100%;height:0;background:rgba(8,5,16,.72);pointer-events:none}
  .skill .sk{position:absolute;right:3px;bottom:1px;font-size:10px;color:#8a7aa0}
  .skill:not(.ready){border-color:rgba(255,215,122,.15)}

  /* tower panel */
  #tpanel{position:fixed;right:14px;top:96px;z-index:12;width:210px;padding:12px;display:none;color:#e8dcc8;pointer-events:auto}
