  #tpstats{font-size:12px;color:#c8bca8;line-height:1.5}
  #tpeh{font-size:11px;color:#8fc8bc;margin:6px 0 10px}
  #tpanel button{display:block;width:100%;margin-top:8px;padding:8px;border-radius:8px;border:1px solid rgba(255,215,122,.35);background:rgba(50,36,20,.85);color:#ffd77a;font-size:13px;cursor:pointer}
  #tpanel button.off{opacity:.45;pointer-events:none}
  #tpx{position:absolute;right:8px;top:8px;width:22px;height:22px;padding:0!important;background:none!important;border:none!important;color:#8a7aa0;font-size:14px}

  /* banner / toast / flash */
  #banner{position:fixed;top:26%;left:50%;transform:translate(-50%,-50%);z-index:14;text-align:center;opacity:0;transition:opacity .3s;pointer-events:none}
  #banner.on{opacity:1}
  #banner .bmain{font-size:30px;color:#ffe0a8;letter-spacing:8px;text-shadow:0 0 18px rgba(255,180,80,.7),0 2px 8px #000}
  #banner .bsub{font-size:14px;color:#c8b090;margin-top:8px;letter-spacing:2px;text-shadow:0 1px 6px #000}
  #toast{position:fixed;bottom:170px;left:50%;transform:translateX(-50%);z-index:14;background:rgba(18,12,28,.9);border:1px solid rgba(255,215,122,.3);color:#e8dcc8;font-size:13px;padding:8px 18px;border-radius:18px;opacity:0;transition:opacity .25s;pointer-events:none}
  #toast.on{opacity:1}
  #flash{position:fixed;inset:0;z-index:9;pointer-events:none;background:radial-gradient(ellipse at center,transparent 55%,rgba(200,30,30,.5));opacity:0}
  #flash.on{animation:fl .5s ease-out}
  @keyframes fl{0%{opacity:1}100%{opacity:0}}

  /* draft overlay */
  #draft{position:fixed;inset:0;z-index:20;display:none;background:rgba(8,5,16,.6);flex-direction:column;align-items:center;justify-content:center;gap:18px}
  #draft .dtitle{font-size:22px;color:#ffe0a8;letter-spacing:6px;text-shadow:0 0 14px rgba(255,190,90,.6)}
  #draft .dcards{display:flex;gap:16px}
  .dcard{width:180px;padding:18px 14px;background:rgba(24,16,38,.95);border:1px solid rgba(255,215,122,.4);border-radius:14px;text-align:center;cursor:pointer;transition:transform .15s,border-color .15s}
  .dcard:hover{transform:translateY(-5px);border-color:#ffd77a;box-shadow:0 0 24px rgba(255,190,90,.3)}
  .dcard .dg{font-size:30px;color:#ffd77a}
