  .dcard .dd{font-size:12px;color:#a898b8;line-height:1.5}
  .dcard .dk{margin-top:10px;font-size:11px;color:#8a7aa0}

  /* title & end */
  #title,#end{position:fixed;inset:0;z-index:30;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 38%,rgba(30,16,44,.55),rgba(8,5,16,.92));text-align:center}
