        iframe.src = src;
        iframe.style.display = "block";
        overlay.style.display = "none";
      });
      fsBtn.addEventListener("click", async () => {
        const el = document.documentElement;
        try { await (el.requestFullscreen?.call(el) || el.webkitRequestFullscreen?.call(el)); } catch {}
      });
