      errors.push(`Game "${getSlug(dirName, meta)}" schema invalid: ${msgs}`);
      continue;
    }

    try {
      if (isIframe(meta)) {
        const msg = await validateIframeGame(dirName, meta);
        if (msg) errors.push(msg);
        else passed++;
      } else {
        const msg = await validateLocalGame(dirName, meta);
        if (msg) errors.push(msg);
        else passed++;
