<title>Orchard Fusion 果园大合成</title>
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#2b1d12;font-family:"Microsoft YaHei",system-ui,sans-serif;user-select:none;-webkit-user-select:none;touch-action:none}
  #gl{position:fixed;inset:0;width:100%;height:100%;display:block}
  .panel{background:rgba(43,26,14,.88);border:1px solid rgba(255,214,140,.28);border-radius:12px;backdrop-filter:blur(3px)}

  /* top hud */
  #hud{position:fixed;left:0;right:0;top:0;z-index:10;display:flex;justify-content:space-between;align-items:flex-start;padding:12px 16px;pointer-events:none;color:#ffe9c8}
  #scorebox{display:flex;flex-direction:column;gap:2px}
  #score{font-size:30px;font-weight:700;color:#ffd77a;text-shadow:0 2px 8px rgba(120,60,10,.6);letter-spacing:1px}
  #best{font-size:12px;color:#d8b98a}
  #nextbox{display:flex;flex-direction:column;align-items:center;gap:4px;pointer-events:auto;cursor:pointer}
  #nextbox .lbl{font-size:12px;color:#d8b98a}
  #nextcv{background:rgba(20,12,6,.55);border:1px solid rgba(255,214,140,.3);border-radius:12px}
  #nexthint{font-size:10px;color:#a8895f}

  /* top-right buttons */
  #tr{position:fixed;right:12px;top:186px;z-index:12;display:flex;flex-direction:column;gap:8px}
  #tr button{width:40px;height:40px;border-radius:10px;border:1px solid rgba(255,214,140,.3);background:rgba(43,26,14,.85);color:#ffd77a;font-size:16px;cursor:pointer}
  #tr button.on{background:rgba(110,70,26,.9)}

  /* combo floaters live on canvas; DOM side only banners/toasts */
  #banner{position:fixed;left:50%;top:26%;transform:translate(-50%,-50%);z-index:14;text-align:center;pointer-events:none;opacity:0;transition:opacity .25s}
  #banner.show{opacity:1}
  #banner .bmain{font-size:34px;font-weight:700;color:#ffe9a8;text-shadow:0 0 18px rgba(255,180,60,.8),0 2px 6px #000;letter-spacing:4px}
    <canvas id="nextcv" width="72" height="72"></canvas>
