  assert(5, !!bodies.find(b => b.tier === 3), '同 tier 碰撞合成出下一级');
  assert(6, S().score >= s0 + SCORES[3], '合成得等级分');

  // -- T7/T8: simultaneous double merge → combo ×1/×2
  startGame();
