// ---------- helpers ----------
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const pad2 = n => String(n).padStart(2, '0');
function fmtTime(sec) {
  if (!Number.isFinite(sec) || sec < 0) return '--:--.--';
  const m = Math.floor(sec / 60);
  const s = sec - m * 60;
  return `${pad2(m)}:${s.toFixed(2).padStart(5, '0')}`;
}
function fmtShort(sec) {
  if (!Number.isFinite(sec) || sec <= 0) return '--:--';
  return fmtTime(sec);
}
function rnd() {
  raceSeed += 0x6D2B79F5;
  let t = raceSeed;
  t = Math.imul(t ^ (t >>> 15), 1 | t);
  t ^= t + Math.imul(t ^ (t >>> 7), 61 | t);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function report(kind, payload = {}) {
  const frame = { kind, ...payload };
  reports.push(frame);
  try {
    if (reportTarget) reportTarget(frame);
    else if (window.parent && window.parent !== window) {
      window.parent.postMessage({ source: 'lightgame', type: 'lightgame:report', payload: frame }, '*');
    }
  } catch (e) {}
}
function toast(msg, dur = 1.8) {
  ui.toast.textContent = msg;
  ui.toast.classList.add('on');
  toastT = dur;
}
function banner(main, sub = '', dur = 1.6) {
