  }
}
setWorld(0);

// ---------- karts ----------
function disposeObject(obj) {
  if (!obj) return;
  scene.remove(obj);
  obj.traverse(o => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of mats) {
        if (m.map && !m.map.userData.shared) m.map.dispose();
        m.dispose();
      }
    }
  });
}
function clearRaceObjects() {
  for (const r of racers) if (r.group) disposeObject(r.group);
  racers = [];
  player = null;
  for (const b of blocks) if (b.mesh) disposeObject(b.mesh);
  blocks = [];
  for (const m of missiles) if (m.mesh) disposeObject(m.mesh);
  missiles = [];
  for (const e of fx) if (e.sprite) disposeObject(e.sprite);
  fx = [];
}
function makeRacer(opts) {
  const group = makeKartModel(opts.color, opts.isPlayer);
  scene.add(group);
  return {
    ...opts,
    group,
    s: opts.s,
    lateral: opts.lateral,
    speed: 0,
    lap: 1,
    crossings: 0,
    finished: false,
    finishT: 0,
    lapTimes: [],
    lapStart: 0,
    boostT: 0,
    boostPow: 0,
    driftT: 0,
    driftCharge: 0,
    driftHeld: false,
    spinT: 0,
    item: null,
    rank: 1,
    fxT: 0,
    steer: 0,
    throttle: 0,
    itemTimer: 1.6 + rnd() * 3,
    ai: opts.ai || null
  };
}
function createRacers() {
  clearRaceObjects();
  raceSeed = 0x1a2b3c4d;
  const startGap = 7.5;
  player = makeRacer({
    isPlayer: true, name: '你', color: COLOR.player,
    s: 7 + (raceMode === 'gp' ? startGap * 2 : 0), lateral: 0
  });
  racers.push(player);
  if (raceMode === 'gp') {
    const lanes = [-3.7, 3.7, 0];
    for (let i = 0; i < 3; i++) {
      const r = makeRacer({
        isPlayer: false, name: AI_NAMES[i], color: COLOR.ai[i],
        s: 7 + startGap * (1 - i), lateral: lanes[i],
        ai: { skill: .93 + i * .035, phase: i * 2.1, mistakeT: 0 }
      });
      racers.push(r);
    }
  }
  updateRanks();
  placeAll(0);
}

// ---------- race control ----------
function startRace(opts = {}) {
