  screen = opts.skipCountdown ? 'race' : 'countdown';
  paused = false;
  raceOver = false;
  dnf = false;
  score = 0;
  raceT = 0;
  countdownT = opts.skipCountdown ? 0 : 3.35;
  lastCountShown = '';
  hitStop = 0;
  trauma = 0;
  hintT = 5;
  toastT = 0;
  ui.toast.classList.remove('on');
  ui.title.classList.add('hide');
  ui.results.classList.add('hide');
  ui.pause.classList.add('hide');
