101	      tone({ f: 900, f2: 320, type: 'square', t: .2, v: .055 });
102	    },
103	    hit() {
104	      if (!ctx) return;
105	      tone({ f: 120, f2: 42, type: 'sawtooth', t: .34, v: .25, decay: .18 });
106	      noise({ t: .18, v: .2, f: 500, q: .7 });
107	    },
108	    drop() { if (ctx) tone({ f: 210, f2: 95, type: 'square', t: .12, v: .09 }); },
109	    lap() {
110	      if (!ctx) return;
111	      [523, 659, 784].forEach((f, i) => tone({ f, type: 'triangle', t: .2, v: .15, at: i * .08 }));
112	    },
113	    win() {
114	      if (!ctx) return;
115	      [523, 659, 784, 1046, 1318].forEach((f, i) => tone({ f, type: 'triangle', t: .32, v: .15, at: i * .11 }));
116	    },
117	    lose() {
118	      if (!ctx) return;
119	      [392, 330, 262, 196].forEach((f, i) => tone({ f, type: 'sawtooth', t: .3, v: .1, at: i * .17, decay: .22 }));
120	    },
121	  };
