123	  // Four-bar pattern, quiet, changes with state.
124	  function musicTick() {
125	    if (!ctx || muted) { musicTimer = 0; return; }
126	    const sets = {
127	      title: { root: 146.8, notes: [0, 7, 12, 15, 12, 7], bpm: 66 },
128	      race: { root: 174.6, notes: [0, 5, 7, 12, 7, 5, 3, 7], bpm: 104 },
129	      result: { root: 130.8, notes: [0, 4, 7, 11, 7, 4], bpm: 72 }
130	    };
131	    const s = sets[musicState] || sets.title;
132	    const beat = 60 / s.bpm;
133	    if (step % 4 === 0) {
134	      const bass = s.root / 2;
135	      tone({ f: bass, type: 'triangle', t: beat * 2.5, v: .07, decay: beat, dest: musG });
136	      tone({ f: s.root * 2, type: 'sine', t: beat * 3, v: .022, decay: beat * 1.5, dest: musG });
137	    }
138	    const note = s.notes[step % s.notes.length];
139	    const f = s.root * Math.pow(2, note / 12) * (step % 8 === 6 ? 2 : 1);
140	    tone({ f, type: 'sine', t: beat * 1.05, v: .036, decay: beat * .7, dest: musG });
141	    if (step % 2 === 1) noise({ t: .025, v: .015, f: 6400, q: .8, dest: musG });
142	    step++;
143	    musicTimer = setTimeout(musicTick, beat * 1000);
144	  }
