146	  return {
147	    ensure,
148	    loaded,
149	    sfx,
150	    engine,
151	    hasCtx: () => !!ctx,
152	    isMuted: () => muted,
153	    setMuted(v) {
154	      muted = !!v;
155	      if (master) master.gain.setTargetAtTime(muted ? 0 : 1, now(), .02);
156	      if (engGain) engGain.gain.setTargetAtTime(muted ? 0 : .05, now(), .05);
157	      if (!muted) this.updateMusic(); else { clearTimeout(musicTimer); musicTimer = 0; }
158	    },
159	    setState(s) { if (s !== musicState) { musicState = s; step = 0; } },
160	    updateMusic() {
161	      if (!ctx || muted || musicTimer) return;
162	      musicTick();
163	    },
164	    stopEngine() { if (engGain) engGain.gain.setTargetAtTime(0, now(), .07); },
165	    dispose() {
166	      clearTimeout(musicTimer); musicTimer = 0;
167	      try { if (ctx) ctx.close(); } catch (e) {}
168	      ctx = null;
169	    }
170	  };
171	}

