31	function rng(seed) {
32	  let t = seed >>> 0;
33	  return function () {
34	    t += 0x6D2B79F5;
35	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
36	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
37	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
38	  };
