41	function controlPoints(shape) {
42	  const pts = [];
43	  const N = 18;
44	  for (let i = 0; i < N; i++) {
45	    const a = i / N * Math.PI * 2;
46	    let rr = 1;
47	    for (const [k, amp, ph] of shape.h) rr += amp * Math.sin(k * a + ph);
48	    const x = Math.cos(a) * shape.rx * rr;
49	    const z = Math.sin(a) * shape.rz * rr;
50	    const y = 5 + shape.yAmp * Math.sin(shape.yFreq * a + 0.7);
51	    pts.push(new THREE.Vector3(x, y, z));
52	  }
53	  return pts;
