const ids=['orbit-kart-grand-prix','shadowspire-ninja','bridgewright','whisper-heist','frostpuck-arena','silkline-swing','lexicon-bastion','aqua-conduit','glyphbeast-trail','emberpin','ironwright-arena','echo-hour','crucible-atelier','twin-tempo-arena'];
const b=await chromium.launch({headless:true,executablePath:'/usr/local/bin/chromium',args:['--no-sandbox','--use-gl=swiftshader']});
let allOk=true;
for (const id of ids) {
 const p=await b.newPage({viewport:{width:1280,height:720}}); const errors=[],warnings=[],reqs=[];
 p.on('console',m=>{if(m.type()==='error')errors.push(m.text()); if(m.type()==='warning')warnings.push(m.text())});
 p.on('pageerror',e=>errors.push(String(e))); p.on('request',r=>reqs.push(r.url()));
 const r=await p.goto(`http://127.0.0.1:8631/games/${id}/`,{waitUntil:'load',timeout:60000});
 await p.waitForTimeout(1000);
 const ext=reqs.filter(u=>!u.startsWith('http://127.0.0.1:8631'));
 const ok=r.status()===200 && errors.length===0 && warnings.filter(w=>!w.includes('GL Driver')).length===0 && ext.length===0;
 if(!ok) allOk=false;
 console.log(JSON.stringify({id,status:r.status(),errors,warnings:warnings.filter(w=>!w.includes('GL Driver')),external:ext,ok})); await p.close();
}
console.log('DIRECT_ALL_OK',allOk); await b.close();
