import { createRequire } from 'module';
const require = createRequire('/tmp/pw/node_modules/');
const { chromium } = require('playwright');
const ids=['orbit-kart-grand-prix','shadowspire-ninja','bridgewright','whisper-heist','frostpuck-arena','silkline-swing','lexicon-bastion','aqua-conduit','glyphbeast-trail','emberpin','ironwright-arena','echo-hour','crucible-atelier','twin-tempo-arena'];
const b=await chromium.launch({headless:true,executablePath:'/usr/local/bin/chromium',args:['--no-sandbox','--use-gl=swiftshader']});
let ok=0;
for(const id of ids){const p=await b.newPage(); await p.goto(`http://127.0.0.1:8640/.scratch/shareall.html?g=${id}`); await p.waitForTimeout(700);
 const r=await p.evaluate(()=>{const w=document.getElementById('f').contentWindow; const fns=['goHome','clickMore','dp_share','play68_submitScore'].map(k=>typeof w[k]); w.dp_share(321); return {fns,shared:window.shared};});
 const pass=r.shared===321 && r.fns.every(x=>x==='function'); if(pass) ok++;
 console.log(id,JSON.stringify(r),pass?'OK':'FAIL'); await p.close();}
console.log('SHARE_OK',ok+'/'+ids.length); await b.close();
